// src/components/Dolar.js
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Line } from 'react-chartjs-2';
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    Filler,
    Tooltip,
    Legend
} from 'chart.js';
import './Dolar.css'; // Asegúrate de importar el archivo CSS

// Registrar las escalas y componentes necesarios
ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Filler, Tooltip, Legend);

const Dolar = () => {
    const [data, setData] = useState([]); // Este estado almacenará los valores del dólar
    const [labels, setLabels] = useState([]); // Este estado almacenará las etiquetas (fechas/hora)
    const [currentPrice, setCurrentPrice] = useState(null); // Estado para almacenar el precio actual
    const apiBaseUrl = 'http://localhost:8000'; // Cambia esto a la URL donde está tu API

    // Función para obtener el valor actual del dólar
    const fetchCurrentDollarValue = async () => {
        try {
            const response = await axios.get(`${apiBaseUrl}/dolar`); // Ajustar la URL
            
            // Inspeccionar la respuesta para entender su estructura
            console.log("Respuesta de la API:", response.data);

            const currentValue = response.data.price; // Ajusta según la estructura de la respuesta
            
            // Verifica si el valor es numérico
            const numericValue = parseFloat(currentValue); // Convierte a número

            if (!isNaN(numericValue)) {
                const currentTime = new Date().toLocaleTimeString(); // Obtener la hora actual

                // Actualiza el estado con el valor actual y la hora
                setData((prevData) => [...prevData, numericValue]);
                setLabels((prevLabels) => [...prevLabels, currentTime]);
                setCurrentPrice(numericValue); // Actualiza el precio actual
            } else {
                console.error("El precio actual no es un número:", currentValue);
                setCurrentPrice(0); // O cualquier valor que desees mostrar en caso de error
            }
        } catch (error) {
            console.error("Error al obtener el precio del dólar:", error);
        }
    };

    useEffect(() => {
        fetchCurrentDollarValue(); // Llama a la función al cargar el componente
        const intervalId = setInterval(() => {
            fetchCurrentDollarValue(); // Llama a la función cada 10 segundos
        }, 10000);

        // Limpia el intervalo al desmontar el componente
        return () => clearInterval(intervalId);
    }, []);

    const chartData = {
        labels: labels,
        datasets: [
            {
                label: 'Precio del Dólar (MXN)',
                data: data,
                borderColor: 'rgba(75,192,192,1)',
                backgroundColor: 'rgba(75,192,192,0.2)',
                fill: true,
            },
        ],
    };

    const chartOptions = {
        scales: {
            y: {
                beginAtZero: false,
                min: 15, // Ajusta según lo que desees
                max: 25, // Ajusta según lo que desees
            },
        },
    };

    return (
        <div className="dolar-container">
            <h1>Precio del Dólar en Tiempo Real</h1>
            {currentPrice !== null ? (
                <h2 className="current-price">${currentPrice.toFixed(2)}</h2> // Muestra el precio actual
            ) : (
                <p>Cargando precio...</p>
            )}
            {data.length > 0 ? (
                <div className="line-chart">
                    <Line data={chartData} options={chartOptions} />
                </div>
            ) : (
                <p>Cargando datos...</p>
            )}
        </div>
    );
};

export default Dolar;
